package queue

import "sync"

// Queue runs one review at a time and reports how deep the backlog is.
type Queue struct {
	mu      sync.Mutex
	pending []Job
	depth   int
}

// Submit enqueues j and never blocks.
func (q *Queue) Submit(j Job) {
	q.mu.Lock()
	defer q.mu.Unlock()
	q.pending = append(q.pending, j)
	q.depth = len(q.pending)
}

// Depth reports the backlog excluding the in-flight job.
func (q *Queue) Depth() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	return q.depth
}

// worker drains the queue in its own goroutine.
func (q *Queue) worker() {
	for {
		j, ok := q.take()
		if !ok {
			return
		}
		q.run(j)
		q.depth = len(q.pending)
	}
}
